#include "papinho_secure_transport.h"
#include "pst_backend.h"
#include <stdio.h>
#include <string.h>
#define CHECK(x,n) if(!(x)){printf("test_diagnostic_creation: FAIL %d\n",n);return n;}
static void config(PST_CONNECTION_CONFIG*c){memset(c,0,sizeof(*c));c->struct_size=sizeof(*c);c->api_version=PST_API_VERSION;c->role=PST_CONNECTION_ROLE_CLIENT;c->provider_selection.struct_size=sizeof(c->provider_selection);c->provider_selection.api_version=PST_API_VERSION;c->provider_selection.mode=PST_BACKEND_SELECTION_EXACT;c->provider_selection.exact_provider_id="missing";c->local_identity.struct_size=sizeof(c->local_identity);c->local_identity.api_version=PST_API_VERSION;c->peer_authentication.struct_size=sizeof(c->peer_authentication);c->peer_authentication.api_version=PST_API_VERSION;c->tls.struct_size=sizeof(c->tls);c->tls.api_version=PST_API_VERSION;c->tls.minimum_version=c->tls.maximum_version=PST_TLS_VERSION_1_2;c->alpn.struct_size=sizeof(c->alpn);c->alpn.api_version=PST_API_VERSION;}
int main(void){PST_RUNTIME_OPTIONS o;PST_CONNECTION_CONFIG c;PST_DIAGNOSTIC_INFO d;pst_runtime*r;pst_connection*connection=NULL;pst_backend_registry_reset();memset(&o,0,sizeof(o));o.struct_size=sizeof(o);o.api_version=PST_API_VERSION;CHECK(pst_runtime_create(&o,&r)==PST_RESULT_OK,1);config(&c);CHECK(pst_diagnostic_info_init(&d)==PST_RESULT_OK,2);CHECK(pst_connection_create_ex(r,&c,&connection,&d)==PST_RESULT_UNSUPPORTED&&!connection,3);CHECK(d.valid&&d.normalized_result==PST_RESULT_UNSUPPORTED&&d.operation==PST_DIAGNOSTIC_OPERATION_RUNTIME,4);c.role=PST_CONNECTION_ROLE_INVALID;CHECK(pst_diagnostic_info_init(&d)==PST_RESULT_OK,5);CHECK(pst_connection_create_ex(r,&c,&connection,&d)==PST_RESULT_INVALID_ARGUMENT&&d.valid,6);pst_runtime_release(r);pst_backend_registry_reset();printf("DIAGNOSTIC_CREATE=PASS COPY=PASS NORMALIZED=PASS\n");printf("test_diagnostic_creation: PASS\n");return 0;}
